function camelToSnake(name) {
  if (typeof name !== 'string') {
    throw new TypeError();
  }

  if (name.length === 0) {
    return '';
  }

  let result = '';
  let i = 0;

  while (i < name.length) {
    const char = name[i];
    const isUpper = char >= 'A' && char <= 'Z';
    const isLower = char >= 'a' && char <= 'z';
    const isDigit = char >= '0' && char <= '9';

    if (char === '_') {
      result += '_';
      i++;
      continue;
    }

    if (isUpper) {
      // Check if this is part of an acronym (consecutive uppercase letters)
      let j = i;
      while (j < name.length && name[j] >= 'A' && name[j] <= 'Z') {
        j++;
      }

      // If followed by a lowercase letter, the last uppercase starts the next word
      if (j < name.length && name[j] >= 'a' && name[j] <= 'z') {
        // Add underscore before the acronym if there's content and last char wasn't underscore
        if (result.length > 0 && result[result.length - 1] !== '_') {
          result += '_';
        }
        // Add all but the last uppercase letter of the run
        for (let k = i; k < j - 1; k++) {
          result += name[k].toLowerCase();
        }
        i = j - 1; // Will be incremented at end of loop
      } else {
        // All uppercase letters at the end or followed by digit/underscore
        if (result.length > 0 && result[result.length - 1] !== '_') {
          result += '_';
        }
        for (let k = i; k < j; k++) {
          result += name[k].toLowerCase();
        }
        i = j - 1; // Will be incremented at end of loop
      }
    } else if (isLower) {
      result += char;
    } else if (isDigit) {
      result += char;
    }

    i++;
  }

  return result;
}

module.exports = { camelToSnake };
